import type { Table as TanstackTable, TableState } from "@tanstack/react-table";

import { createContext, useContext } from "react";

// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const TableContext = createContext<TanstackTable<any> | null>(null);
export const TableStateContext = createContext<TableState | null>(null);

export const useTable = () => {
  const table = useContext(TableContext);
  const state = useContext(TableStateContext);

  if (!table || !state) {
    throw new Error("useTable must be used within a <Table> component");
  }

  return { ...table, state };
};
